using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00007 : ControllerTestBase
    {
        [TestMethod]
        public void Each_Controller_Method_Must_Have_Only_One_Http_Method_Attribute()
        {
            var multipleHttpActionsOnOneMethod = (from controller in Controllers
                                                  from method in controller.Methods
                                                  where method.Attributes.Count(attribute => attribute.Name.StartWith("Http")) > 1
                                                  select new
                                                  {
                                                      ErrorClass = controller.FullQualifiedName,
                                                      Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:      {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
MethodName: {method.Name}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

[HttpGet()] // Please use for your use case specific correct http action
{method.MethodValue.Split(Environment.NewLine).Where(line => line.DoesNotContain("Http")).Flatten(Environment.NewLine).FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                                  }).ToImmutableList();

            Assert.IsTrue(multipleHttpActionsOnOneMethod.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00007

Multiple http actions on one controller method detected. Please use one http action for one method. Findings {multipleHttpActionsOnOneMethod.Count}': {Environment.NewLine}{multipleHttpActionsOnOneMethod.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }


}
